@using sv_55779ac36e2a4ec4b5d281df127b5b76.Models

<div class="personal-info-step">
    <h3>Personal Information</h3>

    <div class="form-group">
        <label for="fullName">Full Name *</label>
        <input id="fullName" type="text" class="form-control" value="@FullName"
               @oninput="e => FullName = e.Value?.ToString() ?? string.Empty" />
        @if (errors.ContainsKey("FullName"))
        {
            <span class="validation-error">@errors["FullName"]</span>
        }
    </div>

    <div class="form-group">
        <label for="email">Email *</label>
        <input id="email" type="email" class="form-control" value="@Email"
               @oninput="e => Email = e.Value?.ToString() ?? string.Empty" />
        @if (errors.ContainsKey("Email"))
        {
            <span class="validation-error">@errors["Email"]</span>
        }
    </div>

    <div class="form-group">
        <label for="phone">Phone *</label>
        <input id="phone" type="tel" class="form-control" value="@Phone"
               @oninput="e => Phone = e.Value?.ToString() ?? string.Empty" />
        @if (errors.ContainsKey("Phone"))
        {
            <span class="validation-error">@errors["Phone"]</span>
        }
    </div>

    <div class="form-group">
        <label for="address">Address *</label>
        <textarea id="address" class="form-control" @oninput="e => Address = e.Value?.ToString() ?? string.Empty">@Address</textarea>
        @if (errors.ContainsKey("Address"))
        {
            <span class="validation-error">@errors["Address"]</span>
        }
    </div>

    <div class="step-buttons">
        <button class="btn btn-primary" @onclick="HandleNext" disabled="@isValidating">
            @if (isValidating)
            {
                <span>Validating...</span>
            }
            else
            {
                <span>Next</span>
            }
        </button>
    </div>
</div>

@code {
    [Parameter] public PersonalInfo? Data { get; set; }
    [Parameter] public EventCallback<PersonalInfo> OnNext { get; set; }
    [Parameter] public IApplicationService ApplicationService { get; set; } = default!;

    private string FullName = string.Empty;
    private string Email = string.Empty;
    private string Phone = string.Empty;
    private string Address = string.Empty;
    private bool isValidating;
    private Dictionary<string, string> errors = new();

    protected override void OnParametersSet()
    {
        if (Data is not null)
        {
            FullName = Data.FullName;
            Email = Data.Email;
            Phone = Data.Phone;
            Address = Data.Address;
        }
    }

    private async Task HandleNext()
    {
        errors.Clear();

        if (string.IsNullOrWhiteSpace(FullName))
            errors["FullName"] = "Full name is required.";
        if (string.IsNullOrWhiteSpace(Email))
            errors["Email"] = "Email is required.";
        if (string.IsNullOrWhiteSpace(Phone))
            errors["Phone"] = "Phone is required.";
        if (string.IsNullOrWhiteSpace(Address))
            errors["Address"] = "Address is required.";

        if (errors.Count > 0) return;

        isValidating = true;
        try
        {
            var emailValid = await ApplicationService.ValidateEmailAsync(Email);
            if (!emailValid)
            {
                errors["Email"] = "Email address is not valid.";
                return;
            }

            var info = new PersonalInfo(FullName.Trim(), Email.Trim(), Phone.Trim(), Address.Trim());
            await OnNext.InvokeAsync(info);
        }
        finally
        {
            isValidating = false;
        }
    }
}

@using sv_55779ac36e2a4ec4b5d281df127b5b76.Models

<div class="work-entry-form">
    <div class="entry-header">
        <h5>Position @(Index + 1)</h5>
        @if (ShowRemove)
        {
            <button class="btn btn-sm btn-outline-danger" @onclick="HandleRemove">Remove</button>
        }
    </div>

    <div class="form-group">
        <label>Company Name *</label>
        <input type="text" class="form-control" value="@Company"
               @oninput="e => { Company = e.Value?.ToString() ?? string.Empty; NotifyChanged(); }" />
    </div>

    <div class="form-group">
        <label>Job Title *</label>
        <input type="text" class="form-control" value="@Title"
               @oninput="e => { Title = e.Value?.ToString() ?? string.Empty; NotifyChanged(); }" />
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Start Date *</label>
            <input type="date" class="form-control" value="@StartDate.ToString("yyyy-MM-dd")"
                   @onchange="e => { StartDate = DateTime.Parse(e.Value?.ToString() ?? DateTime.Today.ToString("yyyy-MM-dd")); NotifyChanged(); }" />
        </div>

        <div class="form-group">
            <label>End Date</label>
            <input type="date" class="form-control" value="@(EndDate?.ToString("yyyy-MM-dd") ?? "")"
                   disabled="@IsCurrent"
                   @onchange="e => { EndDate = string.IsNullOrEmpty(e.Value?.ToString()) ? null : DateTime.Parse(e.Value.ToString()!); NotifyChanged(); }" />
        </div>
    </div>

    <div class="form-group form-check">
        <input type="checkbox" id="current-@Index" checked="@IsCurrent"
               @onchange="e => { IsCurrent = (bool)(e.Value ?? false); if (IsCurrent) EndDate = null; NotifyChanged(); }" />
        <label for="current-@Index">I currently work here</label>
    </div>

    <div class="form-group">
        <label>Description</label>
        <textarea class="form-control" @oninput="e => { Description = e.Value?.ToString() ?? string.Empty; NotifyChanged(); }">@Description</textarea>
    </div>
</div>

@code {
    [Parameter] public int Index { get; set; }
    [Parameter] public bool ShowRemove { get; set; }
    [Parameter] public WorkEntry? Entry { get; set; }
    [Parameter] public EventCallback<WorkEntry> OnChanged { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }

    private string Company = string.Empty;
    private string Title = string.Empty;
    private DateTime StartDate = DateTime.Today;
    private DateTime? EndDate;
    private bool IsCurrent;
    private string Description = string.Empty;

    protected override void OnParametersSet()
    {
        if (Entry is not null)
        {
            Company = Entry.Company;
            Title = Entry.Title;
            StartDate = Entry.StartDate;
            EndDate = Entry.EndDate;
            IsCurrent = Entry.EndDate is null;
            Description = Entry.Description;
        }
    }

    private void NotifyChanged()
    {
        var entry = new WorkEntry(Company, Title, StartDate, IsCurrent ? null : EndDate, Description);
        OnChanged.InvokeAsync(entry);
    }

    private async Task HandleRemove()
    {
        await OnRemove.InvokeAsync();
    }
}

@using sv_55779ac36e2a4ec4b5d281df127b5b76.Models

<div class="work-history-step">
    <h3>Work History</h3>

    @for (int i = 0; i < entries.Count; i++)
    {
        var index = i;
        <WorkEntryForm Index="index"
                       Entry="entries[index]"
                       ShowRemove="entries.Count > 1"
                       OnChanged="e => UpdateEntry(index, e)"
                       OnRemove="() => RemoveEntry(index)" />
    }

    <button class="btn btn-outline-secondary" @onclick="AddEntry">+ Add Another Position</button>

    @if (!string.IsNullOrEmpty(errorMessage))
    {
        <div class="validation-error">@errorMessage</div>
    }

    <div class="step-buttons">
        <button class="btn btn-secondary" @onclick="HandleBack">Back</button>
        <button class="btn btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter] public WorkHistory? Data { get; set; }
    [Parameter] public EventCallback<WorkHistory> OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private List<WorkEntry> entries = new();
    private string? errorMessage;

    protected override void OnParametersSet()
    {
        if (Data is not null && Data.Entries.Count > 0)
        {
            entries = Data.Entries.ToList();
        }
        else if (entries.Count == 0)
        {
            entries.Add(new WorkEntry(string.Empty, string.Empty, DateTime.Today, null, string.Empty));
        }
    }

    private void AddEntry()
    {
        entries.Add(new WorkEntry(string.Empty, string.Empty, DateTime.Today, null, string.Empty));
    }

    private void RemoveEntry(int index)
    {
        if (entries.Count > 1)
        {
            entries.RemoveAt(index);
        }
    }

    private void UpdateEntry(int index, WorkEntry entry)
    {
        if (index < entries.Count)
        {
            entries[index] = entry;
        }
    }

    private async Task HandleNext()
    {
        errorMessage = null;

        foreach (var entry in entries)
        {
            if (string.IsNullOrWhiteSpace(entry.Company) || string.IsNullOrWhiteSpace(entry.Title))
            {
                errorMessage = "Each position must have a company name and job title.";
                return;
            }
        }

        await OnNext.InvokeAsync(new WorkHistory(entries.ToList()));
    }

    private async Task HandleBack()
    {
        await OnBack.InvokeAsync();
    }
}

@using sv_55779ac36e2a4ec4b5d281df127b5b76.Models

<div class="reference-form">
    <div class="entry-header">
