@using sv_55779ac36e2a4ec4b5d281df127b5b76.Models

<div class="references-step">
    <h3>References</h3>
    <p class="text-muted">Please provide 2–3 professional references.</p>

    @for (int i = 0; i < references.Count; i++)
    {
        var index = i;
        <ReferenceForm Index="index"
                       Data="references[index]"
                       ShowRemove="references.Count > 2"
                       OnChanged="e => UpdateReference(index, e)"
                       OnRemove="() => RemoveReference(index)" />
    }

    @if (references.Count < 3)
    {
        <button class="btn btn-outline-secondary" @onclick="AddReference">+ Add Reference</button>
    }

    @if (!string.IsNullOrEmpty(errorMessage))
    {
        <div class="validation-error">@errorMessage</div>
    }

    <div class="step-buttons">
        <button class="btn btn-secondary" @onclick="HandleBack">Back</button>
        <button class="btn btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter] public List<Reference>? Data { get; set; }
    [Parameter] public EventCallback<List<Reference>> OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private List<Reference> references = new();
    private string? errorMessage;

    protected override void OnParametersSet()
    {
        if (Data is not null && Data.Count > 0)
        {
            references = Data.ToList();
        }
        else if (references.Count == 0)
        {
            references.Add(new Reference(string.Empty, string.Empty, string.Empty, string.Empty));
            references.Add(new Reference(string.Empty, string.Empty, string.Empty, string.Empty));
        }
    }

    private void AddReference()
    {
        if (references.Count < 3)
        {
            references.Add(new Reference(string.Empty, string.Empty, string.Empty, string.Empty));
        }
    }

    private void RemoveReference(int index)
    {
        if (references.Count > 2)
        {
            references.RemoveAt(index);
        }
    }

    private void UpdateReference(int index, Reference reference)
    {
        if (index < references.Count)
        {
            references[index] = reference;
        }
    }

    private async Task HandleNext()
    {
        errorMessage = null;

        foreach (var r in references)
        {
            if (string.IsNullOrWhiteSpace(r.Name) || string.IsNullOrWhiteSpace(r.Relationship)
                || string.IsNullOrWhiteSpace(r.Email) || string.IsNullOrWhiteSpace(r.Phone))
            {
                errorMessage = "All reference fields are required.";
                return;
            }
        }

        await OnNext.InvokeAsync(references.ToList());
    }

    private async Task HandleBack()
    {
        await OnBack.InvokeAsync();
    }
}

@using sv_55779ac36e2a4ec4b5d281df127b5b76.Models

<div class="review-step">
    <h3>Review & Submit</h3>
    <p class="text-muted">Please review your application before submitting.</p>

    @if (IsSubmitted)
    {
