@code {
    [Parameter] public PersonalInfo? Data { get; set; }
    [Parameter] public EventCallback<PersonalInfo> OnNext { get; set; }
    [Parameter] public IApplicationService ApplicationService { get; set; } = default!;

    private string FullName = string.Empty;
    private string Email = string.Empty;
    private string Phone = string.Empty;
    private string Address = string.Empty;
    private bool isValidating;
    private Dictionary<string, string> errors = new();

    protected override void OnParametersSet()
    {
        if (Data is not null)
        {
            FullName = Data.FullName;
            Email = Data.Email;
            Phone = Data.Phone;
            Address = Data.Address;
        }
    }

    private async Task HandleNext()
    {
        errors.Clear();

        if (string.IsNullOrWhiteSpace(FullName))
            errors["FullName"] = "Full name is required.";
        if (string.IsNullOrWhiteSpace(Email))
            errors["Email"] = "Email is required.";
        if (string.IsNullOrWhiteSpace(Phone))
            errors["Phone"] = "Phone is required.";
        if (string.IsNullOrWhiteSpace(Address))
            errors["Address"] = "Address is required.";

        if (errors.Count > 0) return;

        isValidating = true;
        try
        {
            var emailValid = await ApplicationService.ValidateEmailAsync(Email);
            if (!emailValid)
            {
                errors["Email"] = "Email address is not valid.";
                return;
            }

            var info = new PersonalInfo(FullName.Trim(), Email.Trim(), Phone.Trim(), Address.Trim());
            await OnNext.InvokeAsync(info);
        }
        finally
        {
            isValidating = false;
        }
    }
}

