{"file_text": "@using sv_55779ac36e2a4ec4b5d281df127b5b76.Models

<div class="review-step">
    <h3>Review & Submit</h3>
    <p class="text-muted">Please review your application before submitting.</p>

    @if (IsSubmitted)
    {
        <div class="submission-confirmation">
            <h4>&#10003; Application Submitted Successfully!</h4>
            <p>Your application ID is: <strong>@ApplicationId</strong></p>
            <p>Thank you for applying. We will be in touch soon.</p>
        </div>
    }
    else
    {
        <div class="review-section">
            <div class="section-header">
                <h4>Personal Information</h4>
                <button class="btn btn-sm btn-link" @onclick="() => EditStep(0)">Edit</button>
            </div>
            @if (Personal is not null)
            {
                <dl>
                    <dt>Name</dt><dd>@Personal.FullName</dd>
                    <dt>Email</dt><dd>@Personal.Email</dd>
                    <dt>Phone</dt><dd>@Personal.Phone</dd>
                    <dt>Address</dt><dd>@Personal.Address</dd>
                </dl>
            }
        </div>

        <div class="review-section">
            <div class="section-header">
                <h4>Work History</h4>
                <button class="btn btn-sm btn-link" @onclick="() => EditStep(1)">Edit</button>
            </div>
            @if (Work is not null)
            {
                @foreach (var entry in Work.Entries)
                {
                    <div class="work-entry-review">
                        <strong>@entry.Title</strong> at <strong>@entry.Company</strong>
                        <div class="text-muted">
                            @entry.StartDate.ToString("MMM yyyy") –
                            @(entry.EndDate?.ToString("MMM yyyy") ?? "Present")
                        </div>
                        @if (!string.IsNullOrWhiteSpace(entry.Description))
                        {
                            <p>@entry.Description</p>
                        }
                    </div>
                }
            }
        </div>

        <div class="review-section">
            <div class="section-header">
                <h4>References</h4>
                <button class="btn btn-sm btn-link" @onclick="() => EditStep(2)">Edit</button>
            </div>
            @if (References is not null)
            {
                @foreach (var r in References)
                {
                    <div class="reference-review">
                        <strong>@r.Name</strong> (@r.Relationship)
                        <div class="text-muted">@r.Email · @r.Phone</div>
                    </div>
                }
            }
        </div>

        <div class="review-section">
            <div class="section-header">
                <h4>Cover Letter</h4>
                <button class="btn btn-sm btn-link" @onclick="() => EditStep(3)">Edit</button>
            </div>
            <p class="cover-letter-preview">@CoverLetter</p>
        </div>

        @if (!string.IsNullOrEmpty(errorMessage))
        {
            <div class="validation-error">@errorMessage</div>
        }

        <div class="step-buttons">
            <button class="btn btn-secondary" @onclick="HandleBack">Back</button>
            <button class="btn btn-success btn-lg" @onclick="HandleSubmit" disabled="@isSubmitting">
                @if (isSubmitting)
                {
                    <span>Submitting...</span>
                }
                else
                {
                    <span>Submit Application</span>
                }
            </button>
        </div>
    }
</div>

@code {
    [Parameter] public PersonalInfo? Personal { get; set; }
    [Parameter] public WorkHistory? Work { get; set; }
    [Parameter] public List<Reference>? References { get; set; }
    [Parameter] public string? CoverLetter { get; set; }
    [Parameter] public EventCallback<int> OnEditStep { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }
    [Parameter] public EventCallback<int> OnSubmitted { get; set; }
    [Parameter] public IApplicationService ApplicationService { get; set; } = default!;

    private bool isSubmitting;
    private bool IsSubmitted;
    private int ApplicationId;
    private string? errorMessage;

    private async Task EditStep(int step)
    {
        await OnEditStep.InvokeAsync(step);
    }

    private async Task HandleBack()
    {
        await OnBack.InvokeAsync();
    }

    private async Task HandleSubmit()
    {
        errorMessage = null;
        isSubmitting = true;

        try
        {
            var application = new JobApplication(Personal!, Work!, References!, CoverLetter!);
            ApplicationId = await ApplicationService.SubmitApplicationAsync(application);
            IsSubmitted = true;
            await OnSubmitted.InvokeAsync(ApplicationId);
        }
        catch (Exception ex)
        {
            errorMessage = $"Submission failed: {ex.Message}. Please try again.";
        }
        finally
        {
            isSubmitting = false;
        }
    }
}
