@page "/apply"
@using sv_55779ac36e2a4ec4b5d281df127b5b76.Models
@inject IApplicationService ApplicationService
@rendermode InteractiveServer

<PageTitle>Job Application</PageTitle>

<div class="apply-page">
    <h2>Job Application</h2>

    <StepIndicator CurrentStep="currentStep" OnStepSelected="GoToStep" />

    @switch (currentStep)
    {
        case 0:
            <PersonalInfoStep Data="personalInfo"
                              ApplicationService="ApplicationService"
                              OnNext="HandlePersonalInfoNext" />
            break;
        case 1:
            <WorkHistoryStep Data="workHistory"
                             OnNext="HandleWorkHistoryNext"
                             OnBack="GoBack" />
            break;
        case 2:
            <ReferencesStep Data="references"
                            OnNext="HandleReferencesNext"
                            OnBack="GoBack" />
            break;
        case 3:
            <CoverLetterStep Data="coverLetter"
                             OnNext="HandleCoverLetterNext"
                             OnBack="GoBack" />
            break;
        case 4:
            <ReviewStep Personal="personalInfo"
                        Work="workHistory"
                        References="references"
                        CoverLetter="coverLetter"
                        ApplicationService="ApplicationService"
                        OnEditStep="GoToStep"
                        OnBack="GoBack"
                        OnSubmitted="HandleSubmitted" />
            break;
    }
</div>

@code {
    private int currentStep = 0;
    private PersonalInfo? personalInfo;
    private WorkHistory? workHistory;
    private List<Reference>? references;
    private string? coverLetter;

    private void GoToStep(int step)
    {
        currentStep = step;
    }

    private void GoBack()
    {
        if (currentStep > 0)
            currentStep--;
    }

    private void HandlePersonalInfoNext(PersonalInfo info)
    {
        personalInfo = info;
        currentStep = 1;
    }

    private void HandleWorkHistoryNext(WorkHistory work)
    {
        workHistory = work;
        currentStep = 2;
    }

    private void HandleReferencesNext(List<Reference> refs)
    {
        references = refs;
        currentStep = 3;
    }

    private void HandleCoverLetterNext(string letter)
    {
        coverLetter = letter;
        currentStep = 4;
    }

    private void HandleSubmitted(int applicationId)
    {
        // Application was submitted successfully
    }
}

.apply-page {
    max-width: 800px;
    margin: 0 auto;
    padding: 2rem 1rem;
}

.apply-page h2 {
    text-align: center;
    margin-bottom: 1.5rem;
}

::deep .form-group {
    margin-bottom: 1rem;
}

::deep .form-group label {
    display: block;
    font-weight: 600;
    margin-bottom: 0.25rem;
    font-size: 0.9rem;
}

::deep .form-control {
    width: 100%;
    padding: 0.5rem 0.75rem;
    border: 1px solid #ced4da;
    border-radius: 0.375rem;
    font-size: 1rem;
    line-height: 1.5;
}

::deep .form-control:focus {
    border-color: #86b7fe;
    outline: 0;
    box-shadow: 0 0 0 0.25rem rgba(13, 110, 253, 0.25);
}

::deep textarea.form-control {
    min-height: 80px;
    resize: vertical;
}

::deep .form-row {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 1rem;
}

::deep .form-check {
    display: flex;
    align-items: center;
    gap: 0.5rem;
}

::deep .step-buttons {
    display: flex;
    justify-content: space-between;
    margin-top: 2rem;
    padding-top: 1rem;
    border-top: 1px solid #dee2e6;
}

::deep .btn {
    padding: 0.5rem 1.5rem;
    border-radius: 0.375rem;
    font-weight: 500;
    cursor: pointer;
    border: 1px solid transparent;
    font-size: 1rem;
    text-decoration: none;
}

::deep .btn:disabled {
    opacity: 0.65;
    cursor: not-allowed;
}

::deep .btn-primary {
    background-color: #0d6efd;
    color: white;
}

::deep .btn-primary:hover:not(:disabled) {
    background-color: #0b5ed7;
}

::deep .btn-secondary {
    background-color: #6c757d;
    color: white;
}

::deep .btn-secondary:hover:not(:disabled) {
    background-color: #5c636a;
}

::deep .btn-success {
    background-color: #198754;
    color: white;
}

::deep .btn-success:hover:not(:disabled) {
    background-color: #157347;
}

::deep .btn-lg {
    padding: 0.75rem 2rem;
    font-size: 1.1rem;
}

::deep .btn-outline-secondary {
    border-color: #6c757d;
    color: #6c757d;
    background: transparent;
}

::deep .btn-outline-secondary:hover {
    background-color: #6c757d;
    color: white;
}

::deep .btn-outline-danger {
    border-color: #dc3545;
    color: #dc3545;
    background: transparent;
}

::deep .btn-outline-danger:hover {
    background-color: #dc3545;
    color: white;
}

::deep .btn-link {
    color: #0d6efd;
    background: none;
    border: none;
    padding: 0;
    text-decoration: underline;
    cursor: pointer;
}

::deep .btn-sm {
    padding: 0.25rem 0.75rem;
    font-size: 0.85rem;
}

::deep .validation-error {
    color: #dc3545;
    font-size: 0.85rem;
    margin-top: 0.25rem;
}

::deep .text-muted {
    color: #6c757d;
}

::deep .entry-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 0.5rem;
}

::deep .work-entry-form,
::deep .reference-form {
    border: 1px solid #dee2e6;
    border-radius: 0.5rem;
    padding: 1.25rem;
    margin-bottom: 1rem;
}

::deep .cover-letter-textarea {
    min-height: 200px !important;
}

::deep .char-count {
    text-align: right;
    font-size: 0.85rem;
    color: #6c757d;
    margin-top: 0.25rem;
}

::deep .char-count.over-limit {
    color: #dc3545;
    font-weight: bold;
}

::deep .review-section {
    border: 1px solid #dee2e6;
    border-radius: 0.5rem;
    padding: 1.25rem;
    margin-bottom: 1rem;
}

::deep .section-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 0.75rem;
}

::deep .section-header h4 {
    margin: 0;
}

::deep .review-section dl {
    display: grid;
    grid-template-columns: auto 1fr;
    gap: 0.25rem 1rem;
    margin: 0;
}

::deep .review-section dt {
    font-weight: 600;
    color: #6c757d;
}

::deep .work-entry-review,
::deep .reference-review {
    padding: 0.5rem 0;
    border-bottom: 1px solid #f0f0f0;
}

::deep .work-entry-review:last-child,
::deep .reference-review:last-child {
    border-bottom: none;
}

::deep .cover-letter-preview {
    white-space: pre-wrap;
    background: #f8f9fa;
    padding: 1rem;
    border-radius: 0.375rem;
}

::deep .submission-confirmation {
    text-align: center;
    padding: 3rem 1rem;
    background: #d1e7dd;
    border-radius: 0.5rem;
    border: 1px solid #badbcc;
}

::deep .submission-confirmation h4 {
    color: #0f5132;
    margin-bottom: 1rem;
}

