    <div class="entry-header">
        <h5>Position @(Index + 1)</h5>
        @if (ShowRemove)
        {
            <button class="btn btn-sm btn-outline-danger" @onclick="HandleRemove">Remove</button>
        }
    </div>

    <div class="form-group">
        <label>Company Name *</label>
        <input type="text" class="form-control" value="@Company" @oninput="OnCompanyInput" />
    </div>

    <div class="form-group">
        <label>Job Title *</label>
        <input type="text" class="form-control" value="@Title" @oninput="OnTitleInput" />
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Start Date *</label>
            <input type="date" class="form-control" value="@StartDateString" @onchange="OnStartDateChange" />
        </div>

        <div class="form-group">
            <label>End Date</label>
            <input type="date" class="form-control" value="@EndDateString"
                   disabled="@IsCurrent" @onchange="OnEndDateChange" />
        </div>
    </div>

    <div class="form-group form-check">
        <input type="checkbox" id="@CheckboxId" checked="@IsCurrent" @onchange="OnCurrentChange" />
        <label for="@CheckboxId">I currently work here</label>
    </div>

    <div class="form-group">
        <label>Description</label>
        <textarea class="form-control" @oninput="OnDescriptionInput">@Description</textarea>
    </div>
</div>

@code {
    [Parameter] public int Index { get; set; }
    [Parameter] public bool ShowRemove { get; set; }
    [Parameter] public WorkEntry? Entry { get; set; }
    [Parameter] public EventCallback<WorkEntry> OnChanged { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }

    private string Company = string.Empty;
    private string Title = string.Empty;
    private DateTime StartDate = DateTime.Today;
    private DateTime? EndDate;
    private bool IsCurrent;
    private string Description = string.Empty;

    private string StartDateString => StartDate.ToString("yyyy-MM-dd");
    private string EndDateString => EndDate?.ToString("yyyy-MM-dd") ?? "";
    private string CheckboxId => $"current-{Index}";

    protected override void OnParametersSet()
    {
        if (Entry is not null)
        {
            Company = Entry.Company;
            Title = Entry.Title;
            StartDate = Entry.StartDate;
            EndDate = Entry.EndDate;
            IsCurrent = Entry.EndDate is null;
            Description = Entry.Description;
        }
    }

    private void OnCompanyInput(ChangeEventArgs e)
    {
        Company = e.Value?.ToString() ?? string.Empty;
        NotifyChanged();
    }

    private void OnTitleInput(ChangeEventArgs e)
    {
        Title = e.Value?.ToString() ?? string.Empty;
        NotifyChanged();
    }

    private void OnStartDateChange(ChangeEventArgs e)
    {
        if (DateTime.TryParse(e.Value?.ToString(), out var date))
            StartDate = date;
        NotifyChanged();
    }

    private void OnEndDateChange(ChangeEventArgs e)
    {
        var val = e.Value?.ToString();
        EndDate = string.IsNullOrEmpty(val) ? null : DateTime.TryParse(val, out var d) ? d : null;
        NotifyChanged();
    }

    private void OnCurrentChange(ChangeEventArgs e)
    {
        IsCurrent = (bool)(e.Value ?? false);
        if (IsCurrent) EndDate = null;
        NotifyChanged();
    }

    private void OnDescriptionInput(ChangeEventArgs e)
    {
        Description = e.Value?.ToString() ?? string.Empty;
        NotifyChanged();
    }

    private void NotifyChanged()
    {
        var entry = new WorkEntry(Company, Title, StartDate, IsCurrent ? null : EndDate, Description);
        OnChanged.InvokeAsync(entry);
    }

    private async Task HandleRemove()
    {
        await OnRemove.InvokeAsync();
    }
}

